package com.shopsphere;
import jakarta.persistence.*;import java.time.Instant;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import org.springframework.stereotype.Repository;
@Entity @Table(name="inventory")class InventoryEntity{@Id UUID id;@Column(nullable=false,unique=true)UUID productId;@Column(nullable=false,unique=true)String sku;int quantityAvailable;int quantityReserved;int reorderLevel;Instant updatedAt;@Version long version;protected InventoryEntity(){}InventoryEntity(Inventory i){id=i.id();apply(i);}void apply(Inventory i){productId=i.productId();sku=i.sku();quantityAvailable=i.quantityAvailable();quantityReserved=i.quantityReserved();reorderLevel=i.reorderLevel();updatedAt=i.updatedAt();}Inventory domain(){return new Inventory(id,productId,sku,quantityAvailable,quantityReserved,reorderLevel,updatedAt);}}
interface SpringInventoryRepository extends JpaRepository<InventoryEntity,UUID>{@Lock(LockModeType.PESSIMISTIC_WRITE)@org.springframework.data.jpa.repository.Query("select i from InventoryEntity i where i.productId=:id")Optional<InventoryEntity>lockByProductId(@Param("id")UUID id);}
@Repository class JpaInventoryRepository implements InventoryRepository{private final SpringInventoryRepository data;JpaInventoryRepository(SpringInventoryRepository d){data=d;}public Optional<Inventory>find(UUID id){return data.lockByProductId(id).map(InventoryEntity::domain);}public Inventory save(Inventory i){InventoryEntity entity=data.findById(i.id()).orElseGet(()->new InventoryEntity(i));entity.apply(i);return data.save(entity).domain();}}
